/**
 * Resolver golden set: real-world application-form question phrasings with
 * the canonical key each should resolve to. "novel" means no profile key
 * applies (free-text questions drafted per job, or asked of the user).
 *
 * Written from the wording used on Greenhouse, Lever, Ashby and Workday
 * forms, including OFCCP/EEO-1 self-identification language. Legal and
 * demographic questions are deliberately over-represented and reworded.
 *
 * [label, expectedKey, options?]
 */
export type GoldenItem = { label: string; expected: string; type?: string; options?: string[] };

const g = (label: string, expected: string, extra: Partial<GoldenItem> = {}): GoldenItem => ({ label, expected, ...extra });

